{
  "findings": [
    {
      "check_id": "CKV_GCP_83",
      "title": "Ensure PubSub Topics are encrypted with Customer Supplied Encryption Keys (CSEK)",
      "resource": "google_pubsub_topic.notification_trigger",
      "severity": "MEDIUM",
      "explanation": "The PubSub topic is not encrypted with a Customer Supplied Encryption Key (CSEK), potentially allowing unauthorized access to the data it contains."
    }
  ],
  "patched_code": "resource "google_pubsub_topic" "notification_trigger" {
  name = "enterprise-disaster-recovery-orchestration-platform-topic-notification"
  kms_key_name = google_pubsub_topic_iam_member.pubsub_key_admin.id
}

resource "google_pubsub_topic_iam_member" "pubsub_key_admin" {
  topic = google_pubsub_topic.notification_trigger.name
  role   = "roles/pubsub.admin"
  member = "serviceAccount:$(google_project.project.number)-compute@developer.gserviceaccount.com"
}

resource "google_kms_crypto_key_iam_member" "key_admin" {
  crypto_key_id = google_kms_crypto_key.pubsub_key.id
  role          = "roles/cloudkms.cryptoKeyEncrypterDecrypter"
  member        = "serviceAccount:$(google_project.project.number)-compute@developer.gserviceaccount.com"
}

resource "google_kms_crypto_key" "pubsub_key" {
  name            = "pubsub-key"
  key_ring        = google_kms_key_ring.pubsub_key_ring.id
}

resource "google_kms_key_ring" "pubsub_key_ring" {
  name     = "pubsub-key-ring"
  location = "global"
}",
  "fix_summary": "Enabled encryption on the PubSub topic using a Customer Supplied Encryption Key (CSEK) by creating a KMS key ring, crypto key, and assigning the necessary IAM permissions."
}
